#!/usr/bin/env node
/**
 * leakshield — entry point
 * CLI 掃描模式：npx tsx src/cli.ts --cli --text "..."
 * Web 模式：npx tsx src/cli.ts --web
 */
import { initWindowsEncoding } from "./utils/win-encoding.js";
import { runCli } from "./transports/cli.js";
import { runWeb } from "./transports/web.js";
import { HELP_TEXT, isHelpRequest } from "./help.js";
export { BUILTIN_RULES } from "./rules/builtin.js";
export { buildDynamicRules } from "./rules/dynamic.js";
export { redact, getLineCol, getIgnoredLines } from "./scanner/utils.js";
export { scanText } from "./scanner/engine.js";
export { toDecisionResult } from "./decision/model.js";
export { protectText, protectUnknownStrings } from "./decision/ingress.js";
// Security enhancement exports
export { scanTextWithDecoding } from "./scanner/engine.js";
export { sanitizeForScanning, isLikelyHomographAttack, detectSuspiciousUnicode, } from "./scanner/unicode.js";
// ─── Bootstrap ───────────────────────────────────────────────────────────────
// Ensure UTF-8 console on Windows before any I/O
initWindowsEncoding();
const args = process.argv;
const isCliMode = args.includes("--cli");
const isWebMode = args.includes("--web");
const isDoctorMode = args.some((arg) => arg === "--doctor" || arg.startsWith("--doctor="));
const isForgetMode = args.includes("--forget");
const piIndex = args.indexOf("--pi");
const isPiSubcommand = piIndex === -1 && args[2] === "pi";
const isPiMode = piIndex !== -1 || isPiSubcommand || args.includes("--pi-install");
const valueOf = (flag) => {
    const index = args.indexOf(flag);
    return index !== -1 && index + 1 < args.length ? args[index + 1] : undefined;
};
if (isPiMode) {
    console.error("leakshield: `leakshield pi` was removed. pi now runs directly with the LeakShield extension loaded in-process.");
    console.error("leakshield: add node_modules/leakshield/dist/adapters/pi/extension.js as the first entry of pi settings.extensions, or start pi with -e <path>.");
    console.error("leakshield: check the setup with `leakshield --doctor pi`.");
    process.exitCode = 2;
}
else if (isHelpRequest(args)) {
    console.log(HELP_TEXT);
}
else if (isForgetMode) {
    // W2/B5: active erasure of persisted mappings. Content-free output.
    const { runForget } = await import("./forget.js");
    const { defaultStorePath } = await import("./decision/mapping-key.js");
    process.exitCode = runForget({
        all: args.includes("--all"),
        session: valueOf("--session"),
        storePath: valueOf("--path") ?? defaultStorePath(),
    });
}
else if (args.includes("--claude-code-proxy")) {
    const { runClaudeCodeProxy } = await import("./adapters/claude-code/cli.js");
    process.exitCode = await runClaudeCodeProxy(args);
}
else if (isDoctorMode) {
    const { runDoctorCommand } = await import("./doctor-hosts.js");
    process.exitCode = await runDoctorCommand(args);
}
else if (isWebMode) {
    const portIdx = args.indexOf("--port");
    const port = portIdx !== -1 ? parseInt(args[portIdx + 1], 10) || 3000 : 3000;
    await runWeb(port);
}
else if (isCliMode) {
    await runCli();
}
else {
    await runCli();
}

import { en } from "./en.js";
import { zhTW } from "./zh-TW.js";
const SUPPORTED_LOCALES = ["en", "zh-TW"];
function resolveLocale() {
    const lang = process.env.LEAKSHIELD_LANG ?? "en";
    if (lang === "zh-TW" || lang === "zh")
        return "zh-TW";
    return "en";
}
const locale = resolveLocale();
const catalog = locale === "zh-TW" ? zhTW : en;
/**
 * Translate a message key, interpolating `{param}` placeholders.
 *
 * @example
 * t("scan.safe_summary")
 * t("cli.found_files", { count: 12 })
 */
export function t(key, params) {
    let msg = catalog[key] ?? en[key] ?? key;
    if (params) {
        for (const [k, v] of Object.entries(params)) {
            msg = msg.replaceAll(`{${k}}`, String(v));
        }
    }
    return msg;
}
export { locale };

import * as fs from "fs";
import * as path from "path";
import chalk from "chalk";
import { loadConfig } from "../config/loader.js";
import { scanText, redactText, appendWarnings } from "../scanner/engine.js";
import { redactAndVerify } from "../scanner/redaction-verifier.js";
import { sanitizeRedactResultForExport } from "../decision/redaction.js";
import { toDecisionResult } from "../decision/model.js";
import { collectFiles, runWithConcurrency } from "../utils/files.js";
import { validateCliScanPath } from "../utils/path-security.js";
import { t } from "../i18n/index.js";
import { initWindowsEncoding, readFileWithEncoding } from "../utils/win-encoding.js";
export { validateCliScanPath };
const SCAN_CONCURRENCY = 8;
// ─── Severity filter ─────────────────────────────────────────────────────────
const SEVERITY_RANK = { HIGH: 3, MEDIUM: 2, LOW: 1 };
export function filterBySeverity(result, min) {
    const threshold = SEVERITY_RANK[min.toUpperCase()];
    const findings = result.findings.filter((f) => SEVERITY_RANK[f.severity] >= threshold);
    const safe = findings.length === 0;
    const highCount = findings.filter((f) => f.severity === "HIGH").length;
    const medCount = findings.filter((f) => f.severity === "MEDIUM").length;
    const summary = safe
        ? t("scan.safe_summary")
        : t("scan.unsafe_summary", {
            count: findings.length,
            high: highCount,
            med: medCount,
            low: findings.length - highCount - medCount,
        });
    return { ...result, findings, total_findings: findings.length, safe, summary: appendWarnings(summary, result.warnings) };
}
// ─── Decision-aware CLI formatting ──────────────────────────────────────────
const SEPARATOR = "─".repeat(60);
/**
 * Pure function that formats a GuardDecisionResult into CLI output lines.
 *
 * Does NOT write to console — returns an array of strings so callers can
 * test formatting without capturing stdout.
 *
 * | decision | Behaviour                                   |
 * |----------|---------------------------------------------|
 * | ALLOW    | Clean summary, continue normally            |
 * | WARN     | Reminder with findings, then continue       |
 * | CONFIRM  | Warning card with actions (non-interactive) |
 */
export function formatCliDecision(decision, label) {
    const lines = [];
    lines.push("");
    lines.push(chalk.bold(t("cli.scan_target", { label })));
    lines.push(SEPARATOR);
    const DECISION_COLOR = {
        ALLOW: chalk.green,
        WARN: chalk.yellow,
        CONFIRM: chalk.red,
    };
    const colorFn = DECISION_COLOR[decision.decision] ?? ((s) => s);
    if (decision.decision === "ALLOW") {
        lines.push(colorFn(t("scan.safe_summary")));
    }
    else {
        // Decision + Risk title line
        const actionPart = decision.recommendedAction
            ? `  |  Action: ${decision.recommendedAction}`
            : "";
        lines.push(colorFn(`Decision: ${decision.decision}  |  Risk: ${decision.riskLevel}${actionPart}`));
        lines.push(decision.summary);
        lines.push("");
        // Group findings by type
        const byType = {};
        for (const f of decision.findings) {
            if (!byType[f.type])
                byType[f.type] = [];
            byType[f.type].push(f);
        }
        for (const [type, items] of Object.entries(byType)) {
            if (!items)
                continue;
            const severity = items[0].severity;
            const color = severity === "HIGH" ? chalk.red : severity === "MEDIUM" ? chalk.yellow : chalk.gray;
            lines.push(color(`  [${severity}] ${type} — ${t("cli.hits", { count: items.length })}`));
            for (const item of items.slice(0, 5)) {
                const loc = item.line
                    ? chalk.dim(` (line ${item.line})`)
                    : "";
                lines.push(`    • ${item.description}${loc}`);
                lines.push(chalk.dim(t("cli.preview", { preview: item.preview })));
            }
            if (items.length > 5) {
                lines.push(chalk.dim(t("cli.more_of_type", { count: items.length - 5 })));
            }
        }
        // CONFIRM: next step hint
        if (decision.decision === "CONFIRM") {
            lines.push("");
            lines.push(chalk.dim(`💡 ${t("cli.confirm_next_step")}`));
        }
    }
    lines.push("");
    lines.push(SEPARATOR);
    lines.push("");
    return lines;
}
/**
 * Build a decision-oriented JSON object safe for CLI/CI export.
 *
 * Strips `originalContent` and ensures findings carry only transport-safe fields.
 */
export function buildDecisionJsonOutput(decision, label) {
    const { originalContent: _oc, ...safeDecision } = decision;
    return {
        label,
        safe: safeDecision.decision === "ALLOW",
        decision: safeDecision.decision,
        riskLevel: safeDecision.riskLevel,
        summary: safeDecision.summary,
        findings: safeDecision.findings.map((f) => ({
            type: f.type,
            severity: f.severity,
            description: f.description,
            preview: f.preview,
            ...(f.line !== undefined ? { line: f.line } : {}),
        })),
        ...(safeDecision.recommendedAction !== undefined
            ? { recommendedAction: safeDecision.recommendedAction }
            : {}),
        ...(safeDecision.safePreview !== undefined
            ? { safePreview: safeDecision.safePreview }
            : {}),
        ...(safeDecision.redactedContent !== undefined
            ? { redactedContent: safeDecision.redactedContent }
            : {}),
    };
}
/**
 * Print decision-aware output to console (text mode).
 */
function printCliDecision(decision, label) {
    const lines = formatCliDecision(decision, label);
    for (const line of lines) {
        console.log(line);
    }
}
// ─── Text output ─────────────────────────────────────────────────────────────
export function printCliResult(result, label) {
    console.log("");
    console.log(chalk.bold(t("cli.scan_target", { label })));
    console.log("─".repeat(60));
    if (result.safe) {
        console.log(chalk.green(result.summary));
    }
    else {
        console.log(chalk.red(result.summary));
        console.log("");
        const byType = {};
        for (const f of result.findings) {
            if (!byType[f.type])
                byType[f.type] = [];
            byType[f.type].push(f);
        }
        for (const [type, items] of Object.entries(byType)) {
            const severity = items[0].severity;
            const color = severity === "HIGH" ? chalk.red : severity === "MEDIUM" ? chalk.yellow : chalk.gray;
            console.log(color(`\n  [${severity}] ${type} — ${t("cli.hits", { count: items.length })}`));
            for (const item of items.slice(0, 5)) {
                const loc = item.line
                    ? chalk.dim(t("cli.location", { line: item.line, col: item.column ?? 0 }))
                    : "";
                console.log(`    • ${item.description}${loc}`);
                console.log(chalk.dim(t("cli.preview", { preview: item.preview })));
            }
            if (items.length > 5) {
                console.log(chalk.dim(t("cli.more_of_type", { count: items.length - 5 })));
            }
        }
    }
    console.log("");
    console.log(result.safe ? chalk.green("💡 " + result.recommendation) : chalk.red("⚠️  " + result.recommendation));
    console.log("─".repeat(60));
    console.log("");
}
// ─── CLI entry ───────────────────────────────────────────────────────────────
export async function runCli() {
    initWindowsEncoding();
    const args = process.argv.slice(2);
    let config = loadConfig();
    const textIdx = args.indexOf("--text");
    const fileIdx = args.indexOf("--file");
    const dirIdx = args.indexOf("--dir");
    const extIdx = args.indexOf("--ext");
    const fmtIdx = args.indexOf("--format");
    const sevIdx = args.indexOf("--min-severity");
    const outIdx = args.indexOf("--out");
    const stdinMode = args.includes("--stdin");
    const redactMode = args.includes("--redact");
    const dryRun = args.includes("--dry-run");
    const encodingDetection = args.includes("--enable-encoding-detection");
    // Override config if flag is provided
    if (encodingDetection) {
        config = {
            ...config,
            settings: {
                ...config.settings,
                encoding_detection: true,
            },
        };
    }
    const format = args[fmtIdx + 1] === "json" ? "json" : "text";
    const minSeverity = (["high", "medium", "low"].includes(args[sevIdx + 1]) ? args[sevIdx + 1] : "low");
    const allowOutside = args.includes("--allow-outside");
    function output(result, label, originalContent) {
        const filtered = filterBySeverity(result, minSeverity);
        const decision = toDecisionResult(filtered, originalContent, config);
        if (format === "json") {
            console.log(JSON.stringify(buildDecisionJsonOutput(decision, label), null, 2));
        }
        else {
            printCliDecision(decision, label);
        }
        return { filtered, decision };
    }
    // --redact / --dry-run mode (supports --text, --file, --stdin)
    if (redactMode) {
        let inputText = null;
        let label = "(inline text)";
        if (textIdx !== -1 && args[textIdx + 1]) {
            inputText = args[textIdx + 1];
        }
        else if (fileIdx !== -1 && args[fileIdx + 1]) {
            const filePath = path.resolve(args[fileIdx + 1]);
            if (!fs.existsSync(filePath)) {
                console.error(chalk.red(t("cli.error_file_not_found", { path: filePath })));
                process.exit(2);
            }
            inputText = readFileWithEncoding(filePath);
            label = filePath;
        }
        else if (stdinMode || !process.stdin.isTTY) {
            const chunks = [];
            for await (const chunk of process.stdin)
                chunks.push(chunk);
            const raw = Buffer.concat(chunks);
            // UTF-16 input is recognized by BOM; input without a BOM must be UTF-8.
            inputText = (raw[0] === 0xff && raw[1] === 0xfe
                ? new TextDecoder("utf-16le").decode(raw)
                : raw[0] === 0xef && raw[1] === 0xbb && raw[2] === 0xbf
                    ? raw.toString("utf-8").slice(1)
                    : raw.toString("utf-8"))
                .replace(/\r\n/g, "\n");
            label = "(stdin)";
        }
        if (inputText === null) {
            console.error(chalk.red(t("cli.error_redact_no_input")));
            process.exit(2);
        }
        const result = redactText(inputText, config);
        if (dryRun) {
            // Dry-run: show preview only, do not output redacted text
            console.error(chalk.bold(t("cli.dryrun_header", { count: result.total_findings, label })));
            if (result.total_findings === 0) {
                console.error(chalk.green(t("cli.dryrun_safe")));
            }
            else {
                for (const f of result.findings) {
                    const loc = f.line
                        ? chalk.dim(t("cli.dryrun_location", { line: f.line, col: f.column ?? 0 }))
                        : "";
                    console.error(`  ${chalk.yellow(f.type)}${loc} — ${f.description}`);
                    console.error(chalk.dim(t("cli.dryrun_preview", { preview: f.preview, type: f.type })));
                }
            }
            process.exit(result.total_findings > 0 ? 1 : 0);
        }
        const verified = redactAndVerify(inputText, config);
        if (!verified.verified) {
            if (format === "json") {
                console.log(JSON.stringify({
                    label,
                    verified: false,
                    totalFindings: verified.totalFindings,
                    residualFindings: verified.residualFindings,
                    truncated: verified.wasTruncated,
                    summary: verified.summary,
                }, null, 2));
            }
            else {
                console.error(chalk.red(t("cli.redact_incomplete", { residual: verified.residualFindings })));
            }
            process.exit(1);
        }
        if (format === "json") {
            console.log(JSON.stringify({
                label,
                verified: true,
                ...sanitizeRedactResultForExport(result),
            }, null, 2));
        }
        else {
            const outPath = outIdx !== -1 ? args[outIdx + 1] : undefined;
            if (outPath) {
                fs.writeFileSync(path.resolve(outPath), verified.redacted, "utf-8");
                console.error(chalk.green(t("cli.redact_written", { path: path.resolve(outPath) })));
            }
            else {
                process.stdout.write(verified.redacted);
            }
            console.error(chalk.green("\n" + t("cli.redact_verified")));
            console.error(chalk.dim(t("cli.redact_footer", { summary: verified.summary })));
        }
        process.exit(0);
    }
    // --dir 模式
    if (dirIdx !== -1 && args[dirIdx + 1]) {
        let dirPath;
        try {
            dirPath = validateCliScanPath(process.cwd(), args[dirIdx + 1], allowOutside);
        }
        catch (e) {
            console.error(chalk.red(t("cli.error_path", { error: e instanceof Error ? e.message : String(e) })));
            process.exit(2);
        }
        if (!fs.existsSync(dirPath)) {
            console.error(chalk.red(t("cli.error_dir_not_found", { path: dirPath })));
            process.exit(2);
        }
        const extensions = extIdx !== -1 ? args.slice(extIdx + 1).filter((a) => a.startsWith(".")) : undefined;
        if (format === "text") {
            console.log(chalk.bold(t("cli.scan_dir", { path: dirPath })));
            if (extensions)
                console.log(chalk.dim(t("cli.ext_filter", { exts: extensions.join(", ") })));
        }
        const files = collectFiles(dirPath, extensions, 200);
        if (format === "text")
            console.log(chalk.dim(t("cli.found_files", { count: files.length })));
        const jsonResults = [];
        let anyUnsafe = false;
        let skippedFiles = 0;
        const tasks = files.map((f) => async () => {
            try {
                const content = readFileWithEncoding(f);
                return { file: f, content };
            }
            catch {
                return null;
